/**
 * UI strings for every language except English and Hebrew.
 *
 * Keyed by the English source text (see ./t.ts for why). English needs no
 * entry — it is the key. Hebrew needs none either — it is passed inline at
 * each call site.
 *
 * The European entries below are written by hand and cover the shell and the
 * highest-traffic screens. Everything not listed falls back to English,
 * which is a correct answer rather than a broken one — no key can be
 * "missing" in a way a user sees.
 *
 * To fill the rest, and the languages not started here (Arabic, Korean,
 * Japanese, Italian, Portuguese), run:
 *
 *     OPENAI_API_KEY=sk-... node scripts/translate-ui.mjs ar ko ja it pt-BR
 *
 * It collects every t() key from the source, translates only what a language
 * is missing, and writes back here — so generated and hand-written entries
 * live together and there is one place to look. Existing entries are never
 * overwritten.
 */

export type StringTable = Record<string, Record<string, string>>;

