    "Run Now": "Lancer maintenant",
    "The run takes a few minutes on the server — you can leave the page and come back.": "L'exécution prend quelques minutes sur le serveur — vous pouvez quitter la page et revenir.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "S'exécute chaque mardi, la veille de l'analyse hebdomadaire : classe les ~900 titres de l'univers par momentum (50% sur 3 mois, 30% sur 6 mois, 20% sur le volume) et sélectionne le vivier actif — les 80 meilleurs à l'achat et les 20 plus faibles à la vente. Un titre entré dans le vivier y reste au moins une semaine, il est donc certain d'être couvert par l'analyse approfondie hebdomadaire.",
    "Last run changes": "Changements de la dernière exécution",
    "Price data fetched for": "Données de cours récupérées pour",
    "Not enough data to rank — the pool was left unchanged.": "Données insuffisantes pour établir un classement — le vivier est resté inchangé.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "Le fournisseur de données a limité certaines requêtes — le classement s'est appuyé sur des données partielles. Un titre sans données de cours n'est pas activé dans le vivier.",
    "Which stocks are missing? ({n})": "Quels titres manquent ? ({n})",
    "Entered": "Entrés",
