    "Exited": "Sortis",
    "{n} stocks dropped out of the ranking but are held until their deep analysis completes": "{n} titres sont sortis du classement mais sont conservés jusqu'à la fin de leur analyse approfondie",
    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ Cette liste n'est qu'un budget d'analyse : elle décide quels titres reçoivent une analyse IA approfondie cette semaine. En sortir n'est PAS un signal de vente. Un titre détenu par un utilisateur, ou faisant l'objet d'une recommandation active, continue d'être analysé même hors du vivier ; une vente ne provient jamais que d'une véritable analyse.",
