    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "Vérification quotidienne à 07h30. Chaque société qui publie est analysée immédiatement — c'est le moteur principal. Un balayage de tout l'univers sert de filet de sécurité tous les ~80 jours.",
