    "Runs full AI analysis on the stocks in the scan pool (80 LONG + 20 SHORT, up to 140 with sticky holds) — 3 concurrent until done. A stock analyzed in the last 14 days is skipped unless it has reported since. Full-universe coverage comes from the quarterly sweep, not from here.": "Lance l'analyse IA complète sur les titres du vivier (80 à l'achat + 20 à la vente, jusqu'à 140 avec les maintiens) — 3 en parallèle jusqu'à la fin. Un titre analysé dans les 14 derniers jours est ignoré sauf s'il a publié depuis. La couverture de tout l'univers provient du balayage trimestriel, pas d'ici.",
