    "Most scans are failing — this is a price-data problem, not an alerting one.": "La mayoría de los escaneos falla: es un problema de datos de precios, no de alertas.",
    "The scan is working and no confirmed signal changes occurred — nothing to alert on.": "El escaneo funciona y no hubo cambios de señal confirmados: no hay nada que avisar.",
    "News and social scan (paid)": "Escaneo de noticias y redes (de pago)",
