    "Pause paid analyses": "Pausar los análisis de pago",
    "Stops every call that costs money (Claude, GPT, Gemini, Grok). The technical scan and its alerts keep running — they are free.": "Detiene todas las llamadas que cuestan dinero (Claude, GPT, Gemini, Grok). El escaneo técnico y sus alertas siguen funcionando: son gratuitos.",
    "Analyses are paused": "Los análisis están pausados",
    "until": "hasta",
    "Resume now": "Reanudar ahora",
    "Retire stale recommendations": "Retirar recomendaciones obsoletas",
    "Runs daily at 06:00 — past 30 days re-analysed, past 45 days removed from the feed": "Se ejecuta a diario a las 06:00: a partir de 30 días se reanalizan y a partir de 45 se retiran del feed",
    "Run now": "Ejecutar ahora",
