    "Updated": "Actualizados",
    "Pre-Screener": "Preselección",
    "Run Now": "Ejecutar ahora",
    "The run takes a few minutes on the server — you can leave the page and come back.": "La ejecución tarda unos minutos en el servidor: puedes salir de la página y volver.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "Se ejecuta cada martes, la víspera del escaneo semanal: ordena los ~900 valores del universo por momentum (50% a 3 meses, 30% a 6 meses, 20% por volumen) y selecciona el grupo activo, los 80 mejores para comprar y los 20 más débiles para vender. Un valor que entra en el grupo permanece al menos una semana, de modo que tiene garantizada la cobertura del escaneo profundo semanal.",
    "Last run changes": "Cambios de la última ejecución",
    "Price data fetched for": "Datos de precio obtenidos para",
    "Not enough data to rank — the pool was left unchanged.": "Datos insuficientes para ordenar: el grupo quedó sin cambios.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "El proveedor de datos limitó algunas peticiones: la clasificación se decidió con datos parciales. Un valor sin datos de precio no se activa en el grupo.",
    "Which stocks are missing? ({n})": "¿Qué valores faltan? ({n})",
    "Entered": "Entraron",
    "None": "Ninguno",
    "Exited": "Salieron",
    "{n} stocks dropped out of the ranking but are held until their deep analysis completes": "{n} valores salieron de la clasificación pero se mantienen hasta que termine su análisis profundo",
    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ Esta lista es solo un presupuesto de análisis: decide qué valores reciben análisis profundo de IA esta semana. Salir de ella NO es una señal de venta. Un valor que un usuario tiene en cartera, o que cuenta con una recomendación activa, se sigue analizando aunque esté fuera del grupo; una venta solo procede de un análisis real.",
    "Today's Scan Queue ({n} selected)": "Cola de escaneo de hoy ({n} seleccionados)",
    "+ {n} more — show all": "+ {n} más: mostrar todos",
    "{done} of {total} already analyzed": "{done} de {total} ya analizados",
    "not analyzed yet": "aún sin analizar",
    "rejected": "descartado",
    "queued": "en cola",
    "Screener hasn't run yet": "La preselección aún no se ha ejecutado",
    "Click 'Run Now' to score the universe": "Pulsa «Ejecutar ahora» para puntuar el universo",
    "Scored": "Puntuados",
    "In pool": "En el grupo",
    "Earnings Monitoring": "Seguimiento de resultados",
    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "Comprueba a diario a las 07:30. Toda empresa que publica se analiza de inmediato: ese es el motor principal. Un barrido de todo el universo actúa como red de seguridad cada ~80 días.",
    "Checking...": "Comprobando…",
    "Check Now": "Comprobar ahora",
    "Re-queue reporters that never got a real analysis": "Volver a poner en cola las empresas que publicaron y nunca se analizaron de verdad",
    "Re-queue reporters": "Volver a poner en cola",
    "Resume today's quarterly batch (if a deploy killed it)": "Reanudar el lote trimestral de hoy (si un despliegue lo interrumpió)",
    "Resume Quarterly Batch": "Reanudar el lote trimestral",
    "Clear all earnings data from Redis": "Borrar de Redis todos los datos de resultados",
    "Reset": "Restablecer",
