    "Quarterly sweep {quarter}": "Barrido trimestral {quarter}",
    "· batch running now": "· lote en ejecución",
    "{n} remaining. Each analysis takes 1-3 minutes and a batch does up to 75, so one to three hours.": "Quedan {n}. Cada análisis tarda de 1 a 3 minutos y un lote procesa hasta 75, es decir, de una a tres horas.",
    "Batch running — {n} in queue. Watch the scan log.": "Lote en ejecución: {n} en cola. Sigue el registro de escaneos.",
    "A batch is already running — this is not an error. Watch the bar above.": "Ya hay un lote en ejecución: no es un error. Sigue la barra de arriba.",
    "Not started: {reason}{queue}": "No iniciado: {reason}{queue}",
    " (queued: {n})": " (en cola: {n})",
