    "Found {found} new | Reporters this quarter: {total}": "{found} publicaciones nuevas | Empresas que publicaron este trimestre: {total}",
    " | {n} moved back to upcoming (no results published)": " | {n} devueltas a «próximas» (sin resultados publicados)",
    "FMP_API_KEY not set — add it in Railway to enable earnings tracking": "FMP_API_KEY sin definir: añádela en Railway para activar el seguimiento de resultados",
    "Reporters analyzed": "Empresas publicadas y analizadas",
    "{n} reporters still waiting for analysis": "{n} empresas que publicaron siguen esperando análisis",
    "Quarterly scan triggered — {when}": "Escaneo trimestral lanzado — {when}",
    "No full sweep running — new reports are analyzed as they arrive": "No hay barrido completo en curso: las nuevas publicaciones se analizan según llegan",
    "Reported — analysis status": "Publicaron — estado del análisis",
