    "• pending": "• pendiente",
    "report date": "fecha de publicación",
    "analysis date": "fecha de análisis",
    "Every reporter is analyzed eventually; reporters get queue priority. 'queued' = awaiting analysis in an upcoming batch.": "Toda empresa que publica acaba analizándose; tienen prioridad en la cola. «en cola» = esperando análisis en un lote próximo.",
    "Upcoming — not yet reported": "Próximas — aún sin publicar",
    "Last check:": "Última comprobación:",
    "Loading earnings data...": "Cargando datos de resultados…",
    "Run Full AI Scan": "Ejecutar el análisis completo de IA",
    "Runs full AI analysis on the stocks in the scan pool (80 LONG + 20 SHORT, up to 140 with sticky holds) — 3 concurrent until done. A stock analyzed in the last 14 days is skipped unless it has reported since. Full-universe coverage comes from the quarterly sweep, not from here.": "Ejecuta el análisis completo de IA sobre los valores del grupo de escaneo (80 de compra + 20 de venta, hasta 140 con los retenidos), 3 en paralelo hasta terminar. Un valor analizado en los últimos 14 días se omite salvo que haya publicado resultados desde entonces. La cobertura de todo el universo procede del barrido trimestral, no de aquí.",
    "Run Screener": "Ejecutar la preselección",
