    "Scan runs automatically every Wednesday at 09:00 Israel time": "El escaneo se ejecuta automáticamente cada miércoles a las 09:00, hora de Israel",
    "🧪 Simulation Panel — Full Flow Test": "🧪 Panel de simulación — prueba del flujo completo",
    "Test the full system: stock scan → master list → position → TA alert → notification": "Probar todo el sistema: escaneo de valores → lista maestra → posición → alerta técnica → notificación",
