    "Adds {symbol} to your portfolio (10 units) so TA scan alerts fire to you": "Añade {symbol} a tu cartera (10 unidades) para que te lleguen las alertas del escaneo técnico",
    "Run TA Scan Now": "Ejecutar el escaneo técnico ahora",
    "Immediate technical analysis — if BUY/SELL signal, you get an alert": "Análisis técnico inmediato: si hay señal de compra o venta, recibes una alerta",
    "Send Test Notification": "Enviar notificación de prueba",
    "Sends alert to all channels (Push + SMS + Email + Inbox)": "Envía una alerta por todos los canales (push, SMS, correo y bandeja interna)",
    "AI Engines Check": "Comprobación de los motores de IA",
    "Real full analysis of {symbol} — verifies Claude, GPT (news) and Gemini (macro) all fire. Takes 1-3 min, costs ~$0.10-0.25": "Análisis completo real de {symbol}: verifica que Claude, GPT (noticias) y Gemini (macro) se activan. Tarda de 1 a 3 min y cuesta unos 0,10-0,25 $",
    "Admin Channel + Budget Check": "Comprobación del canal de administración y el presupuesto",
    "Sends a test message to the admin channel and shows today's estimated spend + cap": "Envía un mensaje de prueba al canal de administración y muestra el gasto estimado de hoy y el límite",
    "Price Sources Check": "Comprobación de las fuentes de precios",
    "Probes Yahoo, Alpaca, FMP, Finnhub and Polygon one by one on {symbol} and shows which return a price. Free and instant — no AI.": "Consulta Yahoo, Alpaca, FMP, Finnhub y Polygon uno a uno sobre {symbol} y muestra cuáles devuelven un precio. Gratis e inmediato, sin IA.",
    "Download Full Backup": "Descargar copia de seguridad completa",
    "Downloads all data (one CSV per table, zipped) to your machine. Railway only offers backups on the Pro plan — this is the actual safety net. Run it before any database change.": "Descarga todos los datos a tu equipo (un CSV por tabla, en un ZIP). Railway solo ofrece copias de seguridad en el plan Pro: esta es la red de seguridad real. Ejecútala antes de cualquier cambio en la base de datos.",
    "Earnings Check for a Symbol": "Comprobación de resultados de un valor",
    "Shows what every earnings calendar says about {symbol} — what we stored, what Finnhub says about past and future, what Nasdaq says — and the verdict the watcher reaches. Free and instant.": "Muestra lo que dice cada calendario de resultados sobre {symbol}: lo que guardamos, lo que dice Finnhub sobre el pasado y el futuro, lo que dice Nasdaq, y la conclusión a la que llega el sistema. Gratis e inmediato.",
