    "Set real SENDGRID_API_KEY in Railway (not SG.xxxxx). Free up to 100 emails/day. Verify sender at sendgrid.com": "Define una SENDGRID_API_KEY real en Railway (no SG.xxxxx). Gratis hasta 100 correos al día. Verifica el remitente en sendgrid.com",
    "Set real TWILIO_ACCOUNT_SID, AUTH_TOKEN, FROM_NUMBER in Railway. User phone must be +972XXXXXXXXX format": "Define TWILIO_ACCOUNT_SID, AUTH_TOKEN y FROM_NUMBER reales en Railway. El teléfono del usuario debe tener el formato +972XXXXXXXXX",
    "Create Bot via @BotFather → set TELEGRAM_BOT_TOKEN + TELEGRAM_CHAT_ID in Railway. Send /start to bot to get Chat ID": "Crea el bot con @BotFather → define TELEGRAM_BOT_TOKEN y TELEGRAM_CHAT_ID en Railway. Envía /start al bot para obtener el Chat ID",
