    "Pause paid analyses": "Kostenpflichtige Analysen pausieren",
    "Stops every call that costs money (Claude, GPT, Gemini, Grok). The technical scan and its alerts keep running — they are free.": "Stoppt alle kostenpflichtigen Aufrufe (Claude, GPT, Gemini, Grok). Der technische Scan und seine Benachrichtigungen laufen weiter — sie sind kostenlos.",
