    "Runs daily at 06:00 — past 30 days re-analysed, past 45 days removed from the feed": "Läuft täglich um 06:00 Uhr — ab 30 Tagen neu analysiert, ab 45 Tagen aus dem Feed entfernt",
    "Run now": "Jetzt starten",
