    "Pre-Screener": "Vorauswahl",
    "Run Now": "Jetzt starten",
    "The run takes a few minutes on the server — you can leave the page and come back.": "Der Lauf dauert auf dem Server einige Minuten — Sie können die Seite verlassen und später zurückkehren.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "Läuft jeden Dienstag, den Tag vor dem wöchentlichen Scan: Er sortiert alle rund 900 Aktien des Universums nach Momentum (50% über 3 Monate, 30% über 6 Monate, 20% Volumen) und wählt den aktiven Pool aus — die besten 80 für Kaufsignale und die schwächsten 20 für Verkaufssignale. Eine Aktie, die in den Pool kommt, bleibt mindestens eine Woche darin und wird damit sicher vom wöchentlichen Tiefenscan erfasst.",
    "Last run changes": "Änderungen des letzten Laufs",
    "Price data fetched for": "Kursdaten abgerufen für",
    "Not enough data to rank — the pool was left unchanged.": "Zu wenige Daten für eine Rangfolge — der Pool blieb unverändert.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "Der Datenanbieter hat einige Anfragen gedrosselt — die Rangfolge beruht auf unvollständigen Daten. Eine Aktie ohne Kursdaten wird nicht in den Pool aufgenommen.",
    "Which stocks are missing? ({n})": "Welche Aktien fehlen? ({n})",
    "Entered": "Aufgenommen",
    "None": "Keine",
    "Exited": "Ausgeschieden",
    "{n} stocks dropped out of the ranking but are held until their deep analysis completes": "{n} Aktien sind aus der Rangfolge gefallen, werden aber gehalten, bis ihre Tiefenanalyse abgeschlossen ist",
    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ Diese Liste ist nur ein Analysebudget: Sie entscheidet, welche Aktien diese Woche eine KI-Tiefenanalyse erhalten. Sie zu verlassen ist KEIN Verkaufssignal. Eine Aktie, die ein Nutzer hält oder zu der eine aktive Empfehlung besteht, wird auch außerhalb des Pools weiter analysiert; ein Verkauf ergibt sich immer nur aus einer tatsächlichen Analyse.",
    "Today's Scan Queue ({n} selected)": "Scan-Warteschlange von heute ({n} ausgewählt)",
    "+ {n} more — show all": "+ {n} weitere — alle anzeigen",
    "{done} of {total} already analyzed": "{done} von {total} bereits analysiert",
    "not analyzed yet": "noch nicht analysiert",
    "rejected": "abgelehnt",
    "queued": "in der Warteschlange",
    "Screener hasn't run yet": "Die Vorauswahl wurde noch nicht ausgeführt",
    "Click 'Run Now' to score the universe": "Klicken Sie auf „Jetzt starten“, um das Universum zu bewerten",
    "Scored": "Bewertet",
    "In pool": "Im Pool",
    "Earnings Monitoring": "Überwachung der Quartalszahlen",
    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "Prüft täglich um 07:30 Uhr. Jedes Unternehmen, das Zahlen vorlegt, wird sofort analysiert — das ist der Hauptmechanismus. Ein Durchlauf über das gesamte Universum dient als Sicherheitsnetz, etwa alle 80 Tage.",
    "Checking...": "Wird geprüft…",
    "Check Now": "Jetzt prüfen",
    "Re-queue reporters that never got a real analysis": "Unternehmen mit Zahlen, die nie wirklich analysiert wurden, erneut einreihen",
    "Re-queue reporters": "Erneut einreihen",
    "Resume today's quarterly batch (if a deploy killed it)": "Den heutigen Quartalslauf fortsetzen (falls ein Deployment ihn abgebrochen hat)",
    "Resume Quarterly Batch": "Quartalslauf fortsetzen",
