    "Quarterly sweep {quarter}": "Quartalsdurchlauf {quarter}",
    "· batch running now": "· Lauf ist gerade aktiv",
    "{n} remaining. Each analysis takes 1-3 minutes and a batch does up to 75, so one to three hours.": "Noch {n} offen. Jede Analyse dauert 1–3 Minuten und ein Lauf schafft bis zu 75 — also ein bis drei Stunden.",
    "Batch running — {n} in queue. Watch the scan log.": "Lauf aktiv — {n} in der Warteschlange. Verfolgen Sie das Scan-Protokoll.",
    "A batch is already running — this is not an error. Watch the bar above.": "Es läuft bereits ein Durchlauf — das ist kein Fehler. Verfolgen Sie den Balken oben.",
