    "Skipped: {reason}": "Übersprungen: {reason}",
    "Found {found} new | Reporters this quarter: {total}": "{found} neue gefunden | Unternehmen mit Zahlen in diesem Quartal: {total}",
    " | {n} moved back to upcoming (no results published)": " | {n} zurück auf „anstehend“ gesetzt (keine Zahlen veröffentlicht)",
    "FMP_API_KEY not set — add it in Railway to enable earnings tracking": "FMP_API_KEY nicht gesetzt — fügen Sie ihn in Railway hinzu, um die Verfolgung der Quartalszahlen zu aktivieren",
    "Reporters analyzed": "Analysierte Unternehmen mit Zahlen",
    "{n} reporters still waiting for analysis": "{n} Unternehmen mit Zahlen warten noch auf ihre Analyse",
    "Quarterly scan triggered — {when}": "Quartalsscan gestartet — {when}",
    "No full sweep running — new reports are analyzed as they arrive": "Kein vollständiger Durchlauf aktiv — neue Zahlen werden analysiert, sobald sie eintreffen",
    "Reported — analysis status": "Zahlen vorgelegt — Analysestatus",
