    "• pending": "• ausstehend",
    "report date": "Veröffentlichungsdatum",
    "analysis date": "Analysedatum",
    "Every reporter is analyzed eventually; reporters get queue priority. 'queued' = awaiting analysis in an upcoming batch.": "Jedes Unternehmen mit Zahlen wird irgendwann analysiert; sie haben Vorrang in der Warteschlange. „In der Warteschlange“ = wartet in einem der nächsten Läufe auf die Analyse.",
    "Upcoming — not yet reported": "Anstehend — noch keine Zahlen",
    "Last check:": "Letzte Prüfung:",
    "Loading earnings data...": "Quartalsdaten werden geladen…",
    "Run Full AI Scan": "Vollständigen KI-Scan starten",
    "Runs full AI analysis on the stocks in the scan pool (80 LONG + 20 SHORT, up to 140 with sticky holds) — 3 concurrent until done. A stock analyzed in the last 14 days is skipped unless it has reported since. Full-universe coverage comes from the quarterly sweep, not from here.": "Führt die vollständige KI-Analyse für die Aktien im Scan-Pool aus (80 Kauf + 20 Verkauf, bis zu 140 mit gehaltenen Werten) — 3 gleichzeitig bis zum Abschluss. Eine Aktie, die in den letzten 14 Tagen analysiert wurde, wird übersprungen, sofern sie seitdem keine Zahlen vorgelegt hat. Die Abdeckung des gesamten Universums stammt aus dem Quartalsdurchlauf, nicht von hier.",
    "Run Screener": "Vorauswahl starten",
    "Scan Now": "Jetzt scannen",
    "Scanning...": "Scan läuft…",
    "Approved": "Freigegeben",
    "Errors": "Fehler",
    "Scan complete!": "Scan abgeschlossen!",
    "Scanned": "Gescannt",
    "Scan runs automatically every Wednesday at 09:00 Israel time": "Der Scan läuft automatisch jeden Mittwoch um 09:00 Uhr israelischer Zeit",
    "🧪 Simulation Panel — Full Flow Test": "🧪 Simulationsbereich — Test des gesamten Ablaufs",
    "Test the full system: stock scan → master list → position → TA alert → notification": "Das ganze System testen: Aktienscan → Hauptliste → Position → technische Benachrichtigung → Mitteilung",
    "Test symbol:": "Testkürzel:",
    "Claude analyzes {symbol} and decides BUY/SELL/HOLD": "Claude analysiert {symbol} und entscheidet BUY/SELL/HOLD",
    "Create Test Position ({symbol})": "Testposition anlegen ({symbol})",
    "Adds {symbol} to your portfolio (10 units) so TA scan alerts fire to you": "Fügt {symbol} Ihrem Portfolio hinzu (10 Stück), damit die Benachrichtigungen des technischen Scans bei Ihnen ankommen",
    "Run TA Scan Now": "Technischen Scan jetzt starten",
    "Immediate technical analysis — if BUY/SELL signal, you get an alert": "Sofortige technische Analyse — bei einem Kauf- oder Verkaufssignal erhalten Sie eine Benachrichtigung",
    "Send Test Notification": "Testbenachrichtigung senden",
    "Sends alert to all channels (Push + SMS + Email + Inbox)": "Sendet eine Benachrichtigung über alle Kanäle (Push, SMS, E-Mail und Posteingang)",
    "AI Engines Check": "Prüfung der KI-Engines",
    "Real full analysis of {symbol} — verifies Claude, GPT (news) and Gemini (macro) all fire. Takes 1-3 min, costs ~$0.10-0.25": "Echte vollständige Analyse von {symbol} — prüft, ob Claude, GPT (Nachrichten) und Gemini (Makro) alle auslösen. Dauert 1–3 Min., kostet etwa 0,10–0,25 $",
    "Admin Channel + Budget Check": "Prüfung von Admin-Kanal und Budget",
    "Sends a test message to the admin channel and shows today's estimated spend + cap": "Sendet eine Testnachricht an den Admin-Kanal und zeigt die geschätzten Ausgaben von heute sowie die Obergrenze",
    "Price Sources Check": "Prüfung der Kursquellen",
    "Probes Yahoo, Alpaca, FMP, Finnhub and Polygon one by one on {symbol} and shows which return a price. Free and instant — no AI.": "Fragt Yahoo, Alpaca, FMP, Finnhub und Polygon nacheinander zu {symbol} ab und zeigt, welche einen Kurs liefern. Kostenlos und sofort — ohne KI.",
    "Download Full Backup": "Vollständige Sicherung herunterladen",
    "Downloads all data (one CSV per table, zipped) to your machine. Railway only offers backups on the Pro plan — this is the actual safety net. Run it before any database change.": "Lädt alle Daten auf Ihren Rechner herunter (eine CSV je Tabelle, als ZIP). Railway bietet Sicherungen nur im Pro-Tarif — dies ist das eigentliche Sicherheitsnetz. Vor jeder Datenbankänderung ausführen.",
    "Earnings Check for a Symbol": "Quartalszahlen-Prüfung für einen Wert",
    "Shows what every earnings calendar says about {symbol} — what we stored, what Finnhub says about past and future, what Nasdaq says — and the verdict the watcher reaches. Free and instant.": "Zeigt, was jeder Quartalskalender zu {symbol} sagt — was wir gespeichert haben, was Finnhub über Vergangenheit und Zukunft sagt, was die Nasdaq sagt — und zu welchem Schluss das System kommt. Kostenlos und sofort.",
