    "Run Now": "Esegui ora",
    "The run takes a few minutes on the server — you can leave the page and come back.": "L'esecuzione richiede qualche minuto sul server: puoi lasciare la pagina e tornare più tardi.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "Viene eseguita ogni martedì, il giorno prima della scansione settimanale: ordina tutti i circa 900 titoli dell'universo per momentum (50% a 3 mesi, 30% a 6 mesi, 20% sul volume) e seleziona il gruppo attivo, gli 80 migliori per l'acquisto e i 20 più deboli per la vendita. Un titolo che entra nel gruppo vi resta almeno una settimana, quindi è garantito che venga coperto dall'analisi approfondita settimanale.",
    "Last run changes": "Variazioni dell'ultima esecuzione",
    "Price data fetched for": "Dati di prezzo recuperati per",
    "Not enough data to rank — the pool was left unchanged.": "Dati insufficienti per stilare la classifica: il gruppo è rimasto invariato.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "Il fornitore di dati ha limitato alcune richieste: la classifica si basa su dati parziali. Un titolo senza dati di prezzo non viene attivato nel gruppo.",
    "Which stocks are missing? ({n})": "Quali titoli mancano? ({n})",
    "Entered": "Entrati",
    "None": "Nessuno",
    "Exited": "Usciti",
    "{n} stocks dropped out of the ranking but are held until their deep analysis completes": "{n} titoli sono usciti dalla classifica ma vengono mantenuti finché non si conclude la loro analisi approfondita",
    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ Questo elenco è solo un budget di analisi: decide quali titoli ricevono l'analisi IA approfondita questa settimana. Uscirne NON è un segnale di vendita. Un titolo posseduto da un utente, o con una raccomandazione attiva, continua a essere analizzato anche fuori dal gruppo; una vendita nasce sempre e solo da un'analisi vera e propria.",
