    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "Controlla ogni giorno alle 07:30. Ogni società che pubblica i conti viene analizzata subito: è il motore principale. Un giro completo sull'universo fa da rete di sicurezza ogni circa 80 giorni.",
