    "Pre-Screener": "Pré-seleção",
    "Run Now": "Executar agora",
    "The run takes a few minutes on the server — you can leave the page and come back.": "A execução leva alguns minutos no servidor — você pode sair da página e voltar depois.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "Roda toda terça-feira, na véspera da varredura semanal: classifica as cerca de 900 ações do universo por momentum (50% em 3 meses, 30% em 6 meses, 20% pelo volume) e seleciona o grupo ativo — as 80 melhores para compra e as 20 mais fracas para venda. Uma ação que entra no grupo permanece ao menos uma semana, garantindo que seja coberta pela análise profunda semanal.",
    "Last run changes": "Mudanças da última execução",
    "Price data fetched for": "Dados de preço obtidos para",
    "Not enough data to rank — the pool was left unchanged.": "Dados insuficientes para classificar — o grupo permaneceu inalterado.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "O provedor de dados limitou algumas requisições — a classificação foi feita com dados parciais. Uma ação sem dados de preço não é ativada no grupo.",
    "Which stocks are missing? ({n})": "Quais ações estão faltando? ({n})",
