    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ Esta lista é apenas um orçamento de análise: ela decide quais ações recebem análise profunda de IA nesta semana. Sair dela NÃO é sinal de venda. Uma ação que um usuário possui, ou que tem recomendação ativa, continua sendo analisada mesmo fora do grupo; uma venda só vem de uma análise de verdade.",
    "Today's Scan Queue ({n} selected)": "Fila de varredura de hoje ({n} selecionadas)",
