    "Earnings Monitoring": "Monitoramento de balanços",
    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "Verifica diariamente às 07h30. Toda empresa que divulga resultados é analisada de imediato — esse é o motor principal. Uma varredura de todo o universo funciona como rede de segurança a cada ~80 dias.",
