    "Every reporter is analyzed eventually; reporters get queue priority. 'queued' = awaiting analysis in an upcoming batch.": "Toda empresa que divulga acaba sendo analisada e tem prioridade na fila. «na fila» = aguardando análise em um lote futuro.",
