    "Loading earnings data...": "Carregando os dados de balanços…",
    "Run Full AI Scan": "Executar a varredura completa de IA",
    "Runs full AI analysis on the stocks in the scan pool (80 LONG + 20 SHORT, up to 140 with sticky holds) — 3 concurrent until done. A stock analyzed in the last 14 days is skipped unless it has reported since. Full-universe coverage comes from the quarterly sweep, not from here.": "Executa a análise completa de IA nas ações do grupo de varredura (80 de compra + 20 de venda, até 140 com as retidas), 3 em paralelo até terminar. Uma ação analisada nos últimos 14 dias é ignorada, a menos que tenha divulgado resultados nesse período. A cobertura de todo o universo vem da varredura trimestral, não daqui.",
