    "Real full analysis of {symbol} — verifies Claude, GPT (news) and Gemini (macro) all fire. Takes 1-3 min, costs ~$0.10-0.25": "Análise completa real de {symbol} — verifica se Claude, GPT (notícias) e Gemini (macro) são acionados. Leva de 1 a 3 min e custa cerca de US$ 0,10 a 0,25",
    "Admin Channel + Budget Check": "Verificação do canal de administração e do orçamento",
