    "Price Sources Check": "Verificação das fontes de preço",
    "Probes Yahoo, Alpaca, FMP, Finnhub and Polygon one by one on {symbol} and shows which return a price. Free and instant — no AI.": "Consulta Yahoo, Alpaca, FMP, Finnhub e Polygon um a um sobre {symbol} e mostra quais retornam preço. Gratuito e imediato — sem IA.",
    "Download Full Backup": "Baixar backup completo",
    "Downloads all data (one CSV per table, zipped) to your machine. Railway only offers backups on the Pro plan — this is the actual safety net. Run it before any database change.": "Baixa todos os dados para a sua máquina (um CSV por tabela, em ZIP). O Railway só oferece backups no plano Pro — esta é a rede de segurança de verdade. Execute antes de qualquer mudança no banco de dados.",
