    "Run now": "شغّل الآن",
    "Share classes (GOOGL/GOOG)": "فئات الأسهم (GOOGL/GOOG)",
    "Fetches SEC issuer ids. Without them the system cannot tell two tickers are one company": "يجلب معرّفات المُصدِر من هيئة الأوراق المالية. وبدونها لا يستطيع النظام معرفة أن رمزين يعودان للشركة نفسها",
    "Check symbol": "فحص رمز",
    "logins": "تسجيلات دخول",
    "used ": "استُخدم ",
    "not used yet": "لم يُستخدم بعد",
    "Revoke": "إلغاء",
