    "Updated": "حُدِّثت",
    "Pre-Screener": "التصفية الأولية",
    "Run Now": "شغّل الآن",
    "The run takes a few minutes on the server — you can leave the page and come back.": "تستغرق العملية بضع دقائق على الخادم — يمكنك مغادرة الصفحة والعودة لاحقًا.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "يعمل كل ثلاثاء، في اليوم السابق للفحص الأسبوعي: يرتّب نحو 900 سهم في النطاق حسب الزخم (50٪ لثلاثة أشهر، 30٪ لستة أشهر، 20٪ للحجم) ويختار المجموعة النشطة — أفضل 80 للشراء وأضعف 20 للبيع على المكشوف. والسهم الذي يدخل المجموعة يبقى فيها أسبوعًا على الأقل، فيُضمن شموله بالفحص المعمّق الأسبوعي.",
    "Last run changes": "تغييرات آخر تشغيل",
    "Price data fetched for": "جُلبت بيانات الأسعار لـ",
    "Not enough data to rank — the pool was left unchanged.": "البيانات غير كافية للترتيب — بقيت المجموعة دون تغيير.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "قيّد مزوّد البيانات بعض الطلبات — فاستند الترتيب إلى بيانات جزئية. والسهم الذي تنقصه بيانات الأسعار لا يُفعَّل ضمن المجموعة.",
    "Which stocks are missing? ({n})": "أي الأسهم ناقصة؟ ({n})",
    "Entered": "دخلت",
    "None": "لا شيء",
    "Exited": "خرجت",
    "{n} stocks dropped out of the ranking but are held until their deep analysis completes": "خرج {n} سهمًا من الترتيب لكنها تُحفظ حتى يكتمل تحليلها المعمّق",
    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ هذه القائمة ميزانية فحص فحسب: تحدّد أي الأسهم تحصل على تحليل معمّق بالذكاء الاصطناعي هذا الأسبوع. والخروج منها ليس إشارة بيع. فالسهم الذي يملكه مستخدم، أو الذي له توصية نشطة، يظل يُحلَّل حتى خارج المجموعة؛ ولا تصدر توصية بيع إلا عن تحليل فعلي.",
    "Today's Scan Queue ({n} selected)": "قائمة فحص اليوم (اختير {n})",
    "+ {n} more — show all": "+ {n} أخرى — اعرض الكل",
