    "Earnings Monitoring": "مراقبة نتائج الأرباح",
    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "يفحص يوميًا في 07:30. وكل شركة تعلن نتائجها تُحلَّل فورًا — وهذا هو المحرّك الأساسي. أما الجولة الشاملة على كامل النطاق فتعمل كشبكة أمان كل 80 يومًا تقريبًا.",
    "Checking...": "جارٍ الفحص…",
    "Check Now": "افحص الآن",
    "Re-queue reporters that never got a real analysis": "إعادة الشركات التي أعلنت نتائجها ولم تُحلَّل فعليًا إلى قائمة الانتظار",
    "Re-queue reporters": "إعادة إلى قائمة الانتظار",
    "Resume today's quarterly batch (if a deploy killed it)": "استئناف دفعة اليوم الربع سنوية (إذا أوقفها نشر جديد)",
    "Resume Quarterly Batch": "استئناف الدفعة الربع سنوية",
