    "· batch running now": "· الدفعة قيد التشغيل الآن",
    "{n} remaining. Each analysis takes 1-3 minutes and a batch does up to 75, so one to three hours.": "بقي {n}. يستغرق كل تحليل من دقيقة إلى ثلاث، وتعالج الدفعة حتى 75 سهمًا — أي من ساعة إلى ثلاث.",
    "Batch running — {n} in queue. Watch the scan log.": "الدفعة قيد التشغيل — {n} في قائمة الانتظار. تابع سجل الفحوصات.",
    "A batch is already running — this is not an error. Watch the bar above.": "هناك دفعة قيد التشغيل بالفعل — وهذا ليس خطأ. تابع الشريط أعلاه.",
    "Not started: {reason}{queue}": "لم يبدأ: {reason}{queue}",
    " (queued: {n})": " (في الانتظار: {n})",
    "Skipped: {reason}": "تم التخطي: {reason}",
    "Found {found} new | Reporters this quarter: {total}": "وُجد {found} إعلانًا جديدًا | الشركات التي أعلنت هذا الربع: {total}",
    " | {n} moved back to upcoming (no results published)": " | أُعيدت {n} إلى «المرتقبة» (لم تُنشر نتائجها)",
    "FMP_API_KEY not set — add it in Railway to enable earnings tracking": "لم تُضبط FMP_API_KEY — أضِفها في Railway لتفعيل متابعة نتائج الأرباح",
    "Reporters analyzed": "الشركات المعلنة التي حُلِّلت",
