    "Quarterly scan triggered — {when}": "بدأ الفحص الربع سنوي — {when}",
    "No full sweep running — new reports are analyzed as they arrive": "لا توجد جولة شاملة قيد التشغيل — تُحلَّل الإعلانات الجديدة فور ورودها",
    "Reported — analysis status": "أعلنت النتائج — حالة التحليل",
    "{done}/{total} analyzed": "حُلِّلت {done}/{total}",
    "✓ analyzed": "✓ حُلِّلت",
