    "report date": "تاريخ الإعلان",
    "analysis date": "تاريخ التحليل",
    "Every reporter is analyzed eventually; reporters get queue priority. 'queued' = awaiting analysis in an upcoming batch.": "كل شركة تعلن نتائجها تُحلَّل في نهاية المطاف، ولها أولوية في قائمة الانتظار. و«في الانتظار» تعني أنها تنتظر التحليل في دفعة قادمة.",
    "Upcoming — not yet reported": "مرتقبة — لم تُعلن بعد",
    "Last check:": "آخر فحص:",
    "Loading earnings data...": "جارٍ تحميل بيانات الأرباح…",
    "Run Full AI Scan": "تشغيل فحص الذكاء الاصطناعي الكامل",
    "Runs full AI analysis on the stocks in the scan pool (80 LONG + 20 SHORT, up to 140 with sticky holds) — 3 concurrent until done. A stock analyzed in the last 14 days is skipped unless it has reported since. Full-universe coverage comes from the quarterly sweep, not from here.": "يجري تحليلًا كاملًا بالذكاء الاصطناعي لأسهم مجموعة الفحص (80 للشراء و20 للبيع على المكشوف، وحتى 140 مع الأسهم المحتفظ بها) — ثلاثة في وقت واحد حتى الانتهاء. ويُتخطّى أي سهم حُلِّل خلال آخر 14 يومًا ما لم يكن قد أعلن نتائجه منذ ذلك الحين. أما تغطية النطاق كاملًا فتأتي من الجولة الربع سنوية لا من هنا.",
    "Run Screener": "تشغيل التصفية",
