    "🧪 Simulation Panel — Full Flow Test": "🧪 لوحة المحاكاة — اختبار المسار الكامل",
    "Test the full system: stock scan → master list → position → TA alert → notification": "اختبار النظام بأكمله: فحص الأسهم ← القائمة الرئيسية ← المركز ← تنبيه التحليل الفني ← الإشعار",
    "Test symbol:": "رمز الاختبار:",
