    "Create Test Position ({symbol})": "إنشاء مركز اختباري ({symbol})",
    "Adds {symbol} to your portfolio (10 units) so TA scan alerts fire to you": "يضيف {symbol} إلى محفظتك (10 وحدات) لتصلك تنبيهات الفحص الفني",
    "Run TA Scan Now": "تشغيل الفحص الفني الآن",
    "Immediate technical analysis — if BUY/SELL signal, you get an alert": "تحليل فني فوري — وإن ظهرت إشارة شراء أو بيع يصلك تنبيه",
    "Send Test Notification": "إرسال إشعار اختباري",
    "Sends alert to all channels (Push + SMS + Email + Inbox)": "يرسل تنبيهًا عبر جميع القنوات (إشعارات ورسائل نصية وبريد إلكتروني وصندوق الرسائل)",
    "AI Engines Check": "فحص محرّكات الذكاء الاصطناعي",
    "Real full analysis of {symbol} — verifies Claude, GPT (news) and Gemini (macro) all fire. Takes 1-3 min, costs ~$0.10-0.25": "تحليل كامل حقيقي لسهم {symbol} — يتحقّق من عمل Claude وGPT (الأخبار) وGemini (الاقتصاد الكلي) جميعًا. يستغرق من دقيقة إلى ثلاث ويكلّف نحو 0.10–0.25 دولار",
    "Admin Channel + Budget Check": "فحص قناة الإدارة والميزانية",
    "Sends a test message to the admin channel and shows today's estimated spend + cap": "يرسل رسالة اختبارية إلى قناة الإدارة ويعرض الإنفاق التقديري لليوم والسقف",
    "Price Sources Check": "فحص مصادر الأسعار",
    "Probes Yahoo, Alpaca, FMP, Finnhub and Polygon one by one on {symbol} and shows which return a price. Free and instant — no AI.": "يستعلم من Yahoo وAlpaca وFMP وFinnhub وPolygon واحدًا تلو الآخر عن {symbol} ويبيّن أيها يعيد سعرًا. مجاني وفوري — بلا ذكاء اصطناعي.",
    "Download Full Backup": "تنزيل نسخة احتياطية كاملة",
    "Downloads all data (one CSV per table, zipped) to your machine. Railway only offers backups on the Pro plan — this is the actual safety net. Run it before any database change.": "ينزّل جميع البيانات إلى جهازك (ملف CSV لكل جدول داخل ملف ZIP). ولا توفّر Railway نسخًا احتياطية إلا في الخطة Pro — فهذه هي شبكة الأمان الفعلية. شغّله قبل أي تغيير في قاعدة البيانات.",
    "Earnings Check for a Symbol": "فحص نتائج الأرباح لسهم",
    "Shows what every earnings calendar says about {symbol} — what we stored, what Finnhub says about past and future, what Nasdaq says — and the verdict the watcher reaches. Free and instant.": "يعرض ما يقوله كل تقويم أرباح عن {symbol} — ما هو مسجّل لدينا، وما يقوله Finnhub عن الماضي والمستقبل، وما يقوله ناسداك — والنتيجة التي يخلص إليها النظام. مجاني وفوري.",
