    "Set real SENDGRID_API_KEY in Railway (not SG.xxxxx). Free up to 100 emails/day. Verify sender at sendgrid.com": "اضبط SENDGRID_API_KEY حقيقيًا في Railway (وليس SG.xxxxx). مجاني حتى 100 رسالة يوميًا. وثّق المُرسِل على sendgrid.com",
    "Set real TWILIO_ACCOUNT_SID, AUTH_TOKEN, FROM_NUMBER in Railway. User phone must be +972XXXXXXXXX format": "اضبط قيم TWILIO_ACCOUNT_SID وAUTH_TOKEN وFROM_NUMBER الحقيقية في Railway. ويجب أن يكون هاتف المستخدم بصيغة ‎+972XXXXXXXXX",
    "Create Bot via @BotFather → set TELEGRAM_BOT_TOKEN + TELEGRAM_CHAT_ID in Railway. Send /start to bot to get Chat ID": "أنشئ البوت عبر ‎@BotFather ثم اضبط TELEGRAM_BOT_TOKEN وTELEGRAM_CHAT_ID في Railway. وأرسل ‎/start إلى البوت للحصول على Chat ID",
