    "Pre-Screener": "사전 선별",
    "Run Now": "지금 실행",
    "The run takes a few minutes on the server — you can leave the page and come back.": "서버에서 몇 분이 걸립니다. 페이지를 나갔다가 다시 와도 됩니다.",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "주간 스캔 전날인 매주 화요일에 실행됩니다. 유니버스의 약 900개 종목을 모멘텀(3개월 50%, 6개월 30%, 거래량 20%)으로 순위를 매겨 활성 풀을 고릅니다. 매수 상위 80개와 매도 하위 20개입니다. 풀에 들어온 종목은 최소 일주일 유지되므로 주간 심층 스캔의 대상이 되는 것이 보장됩니다.",
    "Last run changes": "마지막 실행의 변동",
    "Price data fetched for": "가격 데이터를 가져온 종목",
    "Not enough data to rank — the pool was left unchanged.": "순위를 매길 데이터가 부족해 풀을 변경하지 않았습니다.",
    "The data provider throttled some requests — the ranking was decided on partial data. A stock without price data is not activated into the pool.": "데이터 제공자가 일부 요청을 제한해 부분 데이터로 순위를 정했습니다. 가격 데이터가 없는 종목은 풀에 편입되지 않습니다.",
    "Which stocks are missing? ({n})": "어떤 종목이 빠졌나요? ({n})",
    "Entered": "편입",
    "None": "없음",
    "Exited": "제외",
    "{n} stocks dropped out of the ranking but are held until their deep analysis completes": "{n}개 종목이 순위에서 밀렸지만 심층 분석이 끝날 때까지 유지됩니다",
    "⚠️ This list is a scanning budget only — it decides which stocks get deep AI analysis this week. Leaving it is NOT a sell signal. A stock a user holds, or one with a live recommendation, keeps being analyzed even outside the pool; a sell only ever comes from an actual analysis.": "⚠️ 이 목록은 분석 예산일 뿐입니다. 이번 주에 어떤 종목이 AI 심층 분석을 받을지 정할 뿐, 목록에서 빠지는 것은 매도 신호가 아닙니다. 사용자가 보유한 종목이나 활성 추천이 있는 종목은 풀 밖에서도 계속 분석되며, 매도는 오직 실제 분석에서만 나옵니다.",
    "Today's Scan Queue ({n} selected)": "오늘의 스캔 대기열 ({n}개 선정)",
    "+ {n} more — show all": "+ {n}개 더 — 전체 보기",
