    "Earnings Monitoring": "실적 발표 모니터링",
    "Checks daily at 07:30. Every company that reports is analyzed immediately — that's the primary engine. A full-universe sweep runs as a safety net every ~80 days.": "매일 07:30에 확인합니다. 실적을 발표한 기업은 즉시 분석되며, 이것이 주된 방식입니다. 전체 유니버스 스윕은 약 80일마다 안전망으로 실행됩니다.",
    "Checking...": "확인 중…",
