    "{n} remaining. Each analysis takes 1-3 minutes and a batch does up to 75, so one to three hours.": "{n}개 남았습니다. 분석 한 건에 1~3분이 걸리고 배치당 최대 75개를 처리하므로 한 시간에서 세 시간 정도입니다.",
    "Batch running — {n} in queue. Watch the scan log.": "배치 실행 중 — 대기열 {n}개. 스캔 기록을 확인하세요.",
    "A batch is already running — this is not an error. Watch the bar above.": "이미 배치가 실행 중입니다. 오류가 아닙니다. 위의 진행 표시줄을 확인하세요.",
