    "Quarterly scan triggered — {when}": "분기 스캔 시작 — {when}",
    "No full sweep running — new reports are analyzed as they arrive": "전체 스윕은 실행 중이 아닙니다. 새 발표는 도착하는 대로 분석됩니다",
    "Reported — analysis status": "발표 완료 — 분석 상태",
