    "✓ analyzed": "✓ 분석됨",
    "⏳ queued": "⏳ 대기 중",
    "• pending": "• 보류",
    "report date": "발표일",
    "analysis date": "분석일",
    "Every reporter is analyzed eventually; reporters get queue priority. 'queued' = awaiting analysis in an upcoming batch.": "발표한 기업은 결국 모두 분석되며 대기열에서 우선순위를 갖습니다. '대기 중'은 다음 배치에서 분석을 기다린다는 뜻입니다.",
    "Upcoming — not yet reported": "예정 — 아직 미발표",
    "Last check:": "마지막 확인:",
    "Loading earnings data...": "실적 데이터를 불러오는 중…",
    "Run Full AI Scan": "전체 AI 스캔 실행",
    "Runs full AI analysis on the stocks in the scan pool (80 LONG + 20 SHORT, up to 140 with sticky holds) — 3 concurrent until done. A stock analyzed in the last 14 days is skipped unless it has reported since. Full-universe coverage comes from the quarterly sweep, not from here.": "스캔 풀의 종목(매수 80개 + 매도 20개, 유지 종목 포함 시 최대 140개)에 대해 전체 AI 분석을 실행합니다. 완료될 때까지 3개씩 동시에 처리합니다. 최근 14일 안에 분석된 종목은 그사이 실적을 발표하지 않았다면 건너뜁니다. 전체 유니버스 커버리지는 여기가 아니라 분기 스윕에서 나옵니다.",
    "Run Screener": "사전 선별 실행",
    "Scan Now": "지금 스캔",
    "Scanning...": "스캔 중…",
    "Approved": "승인됨",
    "Errors": "오류",
    "Scan complete!": "스캔 완료!",
    "Scanned": "스캔됨",
    "Scan runs automatically every Wednesday at 09:00 Israel time": "스캔은 매주 수요일 이스라엘 시간 09:00에 자동 실행됩니다",
    "🧪 Simulation Panel — Full Flow Test": "🧪 시뮬레이션 패널 — 전체 흐름 테스트",
    "Test the full system: stock scan → master list → position → TA alert → notification": "전체 시스템 테스트: 종목 스캔 → 마스터 목록 → 포지션 → 기술적 알림 → 통지",
    "Test symbol:": "테스트 종목:",
    "Claude analyzes {symbol} and decides BUY/SELL/HOLD": "Claude가 {symbol}을(를) 분석해 BUY/SELL/HOLD를 결정합니다",
    "Create Test Position ({symbol})": "테스트 포지션 생성 ({symbol})",
    "Adds {symbol} to your portfolio (10 units) so TA scan alerts fire to you": "{symbol}을(를) 포트폴리오에 10주 추가해 기술적 스캔 알림이 본인에게 오도록 합니다",
    "Run TA Scan Now": "기술적 스캔 지금 실행",
    "Immediate technical analysis — if BUY/SELL signal, you get an alert": "즉시 기술적 분석을 실행하며, 매수·매도 신호가 나오면 알림을 받습니다",
    "Send Test Notification": "테스트 알림 보내기",
    "Sends alert to all channels (Push + SMS + Email + Inbox)": "모든 채널(푸시, SMS, 이메일, 앱 알림함)로 알림을 보냅니다",
    "AI Engines Check": "AI 엔진 점검",
    "Real full analysis of {symbol} — verifies Claude, GPT (news) and Gemini (macro) all fire. Takes 1-3 min, costs ~$0.10-0.25": "{symbol}에 대한 실제 전체 분석입니다. Claude, GPT(뉴스), Gemini(거시)가 모두 작동하는지 확인합니다. 1~3분이 걸리고 약 0.10~0.25달러가 듭니다",
    "Admin Channel + Budget Check": "관리자 채널 및 예산 점검",
    "Sends a test message to the admin channel and shows today's estimated spend + cap": "관리자 채널로 테스트 메시지를 보내고 오늘의 예상 지출과 한도를 표시합니다",
    "Price Sources Check": "가격 소스 점검",
    "Probes Yahoo, Alpaca, FMP, Finnhub and Polygon one by one on {symbol} and shows which return a price. Free and instant — no AI.": "{symbol}에 대해 Yahoo, Alpaca, FMP, Finnhub, Polygon을 하나씩 조회해 어디서 가격이 오는지 보여줍니다. 무료이며 즉시 실행되고 AI를 쓰지 않습니다.",
    "Download Full Backup": "전체 백업 내려받기",
    "Downloads all data (one CSV per table, zipped) to your machine. Railway only offers backups on the Pro plan — this is the actual safety net. Run it before any database change.": "모든 데이터를 내 컴퓨터로 내려받습니다(테이블당 CSV 하나, ZIP 묶음). Railway는 Pro 요금제에서만 백업을 제공하므로 이것이 실제 안전망입니다. 데이터베이스를 변경하기 전에 실행하세요.",
    "Earnings Check for a Symbol": "특정 종목 실적 점검",
    "Shows what every earnings calendar says about {symbol} — what we stored, what Finnhub says about past and future, what Nasdaq says — and the verdict the watcher reaches. Free and instant.": "{symbol}에 대해 각 실적 캘린더가 무엇이라 말하는지 보여줍니다. 저장된 값, Finnhub의 과거·미래 정보, 나스닥의 정보, 그리고 시스템이 내린 판단까지. 무료이며 즉시 실행됩니다.",
    "stored as reported": "발표됨으로 저장",
    "recorded report date": "기록된 발표일",
    "Finnhub — upcoming": "Finnhub — 예정",
    "Finnhub — already reported": "Finnhub — 발표 완료",
    "Nasdaq on recorded date": "기록된 날짜의 나스닥 정보",
    "Batch quotes (screener): ": "일괄 시세 (사전 선별): ",
    "Provider health — last 7 days, from real analyses": "데이터 제공자 상태 — 최근 7일, 실제 분석 기준",
    "Provider": "제공자",
    "OK": "성공",
