    "The run takes a few minutes on the server — you can leave the page and come back.": "サーバー上で数分かかります。ページを離れて後で戻っても構いません。",
    "Runs every Tuesday, the day before the weekly scan, ranking all ~900 universe stocks by momentum (50% 3-month, 30% 6-month, 20% volume) and selects the active pool: top 80 for LONG + weakest 20 for SHORT. A stock that enters the pool is held for at least a week, so it is guaranteed to be covered by the weekly deep scan.": "週次スキャンの前日にあたる毎週火曜に実行されます。ユニバースの約900銘柄をモメンタム（3か月50%、6か月30%、出来高20%）で順位付けし、買い上位80銘柄と売り下位20銘柄を対象群として選びます。対象群に入った銘柄は最低1週間保持されるため、週次の詳細スキャンで必ずカバーされます。",
